window.TECH_LESSONS = [{"t":"Manage Android storage and downloads","u":"اینڈرائیڈ فون کی اسٹوریج اور ڈاؤن لوڈز","g":"Find saved documents, understand storage and free space without losing important files.","points":[["Open Settings → Storage to see what uses space. Labels differ by Android brand.","سیٹنگز میں اسٹوریج دیکھیں کہ کس چیز نے جگہ لی ہے۔"],["Use Files, My Files or your phone's file manager to locate Downloads, Documents and PDFs.","فائل مینیجر میں ڈاؤن لوڈز اور دستاویزات تلاش کریں۔"],["Cache is temporary data, but clearing an app’s data/storage may sign you out or remove local information.","کیش وقتی ڈیٹا ہے؛ Clear data سے اہم معلومات ختم بھی ہو سکتی ہیں۔"],["Check backups before deleting photos; deleting a synced photo may also remove its online copy.","تصویر حذف کرنے سے پہلے بیک اپ چیک کریں؛ کلاؤڈ سے بھی حذف ہو سکتی ہے۔"]],"task":"Find a PDF you downloaded, rename a non-important file if possible, and check your free storage. Delete nothing.","taskUr":"اپنی ڈاؤن لوڈ کی ہوئی پی ڈی ایف تلاش کریں، جگہ دیکھیں، کچھ ڈیلیٹ نہ کریں۔","qa":[{"question":"Your phone shows 'Storage almost full', but WhatsApp photos are important. Best first move?","options":["Delete the full WhatsApp folder","Inspect storage categories and check backed-up files before removing anything","Install a random cleaner app","Factory reset immediately"],"answer":1,"why":"You need to identify safe items and verify copies before deleting personal files."},{"question":"An Android app offers 'Clear cache' and 'Clear storage/data'. Which has the higher risk of deleting local account or app information?","options":["Clear cache","Both guarantee identical results","Clear storage/data","Neither changes anything"],"answer":2,"why":"Clear storage/data resets app data; clearing cache normally removes temporary files."},{"question":"You deleted a photo in a gallery that synchronizes with cloud storage. What is possible?","options":["Deletion also synchronizes to the cloud","Deletion always leaves a separate backup forever","The SIM card saves a copy","The phone automatically emails it to you"],"answer":0,"why":"Sync is not the same as a separate backup."}],"v":null},{"t":"Fix Wi-Fi and mobile-data problems","u":"وائی فائی اور موبائل انٹرنیٹ کی خرابی","g":"Distinguish weak Wi-Fi, internet outages, and mobile-data limits.","points":[["Connected to Wi-Fi does not always mean the router has working internet service.","وائی فائی سے جڑنا اور انٹرنیٹ چلنا دو الگ باتیں ہیں۔"],["If other devices work, check this phone's Wi-Fi connection, VPN, airplane mode and data settings one at a time.","اگر باقی فون چلیں تو اپنے فون کی وائی فائی، VPN اور ڈیٹا سیٹنگ چیک کریں۔"],["Mobile hotspots use the sharing phone's mobile-data allowance, which may have costs.","ہاٹ اسپاٹ سے موبائل ڈیٹا استعمال ہو سکتا ہے اور خرچہ آ سکتا ہے۔"],["Do not reset network settings casually: saved Wi-Fi networks or Bluetooth connections may be lost.","نیٹ ورک ری سیٹ سوچ سمجھ کر کریں؛ پرانے کنکشن مٹ سکتے ہیں۔"]],"task":"Compare whether your home Wi-Fi works on two devices and find Android's Wi-Fi and mobile data settings.","taskUr":"دو آلات پر گھر کا وائی فائی چیک کریں اور فون کی انٹرنیٹ سیٹنگ دیکھیں۔","qa":[{"question":"Your Android phone connects to the home Wi-Fi, but no website loads; everyone else has the same issue. Best hypothesis?","options":["Every phone lost its password at once","The router or internet service may be down","Your phone's camera is broken","You need a bigger SSD"],"answer":1,"why":"An outage affecting multiple devices often points beyond one phone."},{"question":"Wi-Fi works in your home, but fails only in one room. What first test is useful?","options":["Replace your phone's SIM","Factory reset your phone","Move closer to the router and compare signal","Delete your browser bookmarks"],"answer":2,"why":"Location-specific problems may be signal or interference related."},{"question":"You share your mobile hotspot with a tablet. Which connection is carrying the tablet's internet?","options":["Tablet uses no data because hotspot is free","The phone's mobile-data connection","The tablet's camera","Bluetooth storage"],"answer":1,"why":"Hotspots typically share the phone's internet connection, often cellular data."}],"v":null},{"t":"Control app permissions and privacy","u":"ایپس کی اجازتیں اور پرائیویسی","g":"Review who can access your location, camera, files, and notifications.","points":[["Find Settings → Apps (or Privacy/Permission manager) to review permissions. Menu names vary.","سیٹنگز میں Apps یا Privacy سے اجازتیں دیکھیں۔"],["Allow access only when it is needed, for example location 'while using the app' instead of always if appropriate.","ضرورت کے مطابق اجازت دیں، بلا وجہ ہر وقت لوکیشن نہ دیں۔"],["Check the real app publisher in Google Play before installing or updating unfamiliar apps.","گوگل پلے میں اصل بنانے والے کا نام دیکھیں۔"],["Be careful with Accessibility, SMS, notification-listener and 'display over other apps' permissions.","خاص اجازتیں جیسے SMS یا Accessibility بہت سوچ سمجھ کر دیں۔"]],"task":"Review permissions for one frequently used Android app and identify one that is essential and one that is optional.","taskUr":"اینڈرائیڈ میں کسی ایپ کی ضروری اور غیرضروری اجازت دیکھیں۔","qa":[{"question":"A simple calculator app asks to read your SMS messages. Best decision?","options":["Allow because the app is popular","Allow only for a minute","Deny and question why the permission is needed","Turn off Wi-Fi to make permission safe"],"answer":2,"why":"SMS access is unrelated to basic calculation and may expose private codes."},{"question":"A map app can use location only while open. You rarely use it in the background. Most sensible permission?","options":["Allow all the time automatically","Allow while using the app","Disable every phone sensor","Give it access to contacts as well"],"answer":1,"why":"Least-privilege permissions reduce unnecessary exposure."},{"question":"A QR-code app requests Android Accessibility control over your entire screen. What should you do?","options":["Approve because all QR apps need it","Verify why it is requesting such powerful access; decline if unjustified","Give it your Google password","Uninstall the operating system"],"answer":1,"why":"Accessibility can grant broad control, so unexpected requests warrant caution."}],"v":null},{"t":"Scan documents and create a PDF","u":"موبائل سے کاغذ اسکین کر کے پی ڈی ایف بنائیں","g":"Turn one or more paper pages into a clear, correctly named PDF.","points":[["On Android, Google Drive's Scan feature can turn paper documents into PDFs; its button can be a camera icon depending on version.","اینڈرائیڈ پر گوگل ڈرائیو میں Scan سے کاغذ کی پی ڈی ایف بنائیں۔"],["Place paper on a contrasting surface with good light; crop carefully so no text is cut off.","صاف روشنی میں تصویر لیں اور تمام الفاظ صحیح کاٹ کر محفوظ کریں۔"],["Scan extra pages into the same PDF when the app supports it, then choose an understandable filename.","ضرورت ہو تو کئی صفحے ایک پی ڈی ایف میں رکھیں اور اچھا نام دیں۔"],["Before emailing sensitive documents, check the recipient and that the file really opens.","ذاتی دستاویز بھیجنے سے پہلے فائل اور وصول کرنے والے کا پتہ دیکھیں۔"]],"task":"Scan a non-sensitive letter or recipe into a two-page PDF using Google Drive, then find and open the saved file.","taskUr":"کسی عام کاغذ کے دو صفحوں کی پی ڈی ایف بنا کر کھولیں۔","qa":[{"question":"You scanned a two-page letter, but page 2 has a missing corner. Best action?","options":["Send it because the text is probably enough","Rescan the incomplete page and review the final PDF","Change the PDF filename only","Take a screenshot of page 1"],"answer":1,"why":"Reviewing every page prevents incomplete official submissions."},{"question":"An organization requests one PDF containing both sides of a card. Which is most appropriate?","options":["Email two blurry photos without checking","Scan both sides, save as a multi-page PDF, verify both are readable","Convert it into a music file","Send a link to your phone's photo library"],"answer":1,"why":"A readable multi-page PDF meets a one-document request."},{"question":"A PDF stored in Drive is not appearing in your phone's Downloads folder. What explains it?","options":["PDFs cannot be stored online","Drive and local Downloads are different locations","Scanning did not make a PDF","The phone needs more RAM"],"answer":1,"why":"A file can be saved in cloud storage without being downloaded locally."}],"v":{"id":"9-o12O4fIP0","label":"Scan documents into PDFs with Google Drive","start":0}},{"t":"Move files between Android and laptop","u":"فون سے لیپ ٹاپ میں فائلیں منتقل کریں","g":"Choose a safe way to move documents and photos between devices.","points":[["Email attachments, Google Drive, a trusted USB cable or Nearby/Quick Share can transfer files.","ای میل، گوگل ڈرائیو یا یو ایس بی سے فون اور لیپ ٹاپ میں فائل منتقل کریں۔"],["Uploading to Drive makes files accessible from your signed-in devices but may use internet data.","ڈرائیو میں اپ لوڈ کرنے سے دوسرے آلے میں بھی فائل مل سکتی ہے۔"],["A USB cable might charge only; some cables support data too, and Android may ask you to choose File transfer.","کچھ یو ایس بی کیبل صرف چارج کرتی ہیں؛ ڈیٹا کے لیے File transfer چنیں۔"],["Before deleting the original, open the destination copy and confirm it transferred correctly.","اصل فائل حذف کرنے سے پہلے نئی کاپی کھول کر دیکھیں۔"]],"task":"Transfer a harmless photo from an Android phone to a laptop or Google Drive and open the copy.","taskUr":"ایک عام تصویر فون سے لیپ ٹاپ یا ڈرائیو میں لے جا کر کھولیں۔","qa":[{"question":"A laptop charges your Android phone over USB but cannot see its photos. What could you check?","options":["Whether the cable supports data and the phone's USB file-transfer mode","Whether the laptop has a touchscreen","Whether the phone has a SIM PIN","Whether the photo has been printed"],"answer":0,"why":"Charging can work even if the cable or USB mode does not support file transfer."},{"question":"After uploading an important PDF to Drive, you want to erase the phone copy. What should happen first?","options":["Assume the upload worked","Verify the Drive copy opens and consider keeping a separate backup","Turn off the display","Clear Chrome history"],"answer":1,"why":"Always verify the transferred copy before deleting originals."},{"question":"A family member asks you to share one file from Google Drive. What should you check?","options":["That the entire Drive is public","Exactly which file and what access the recipient receives","That they know your Google password","Whether they use the same wallpaper"],"answer":1,"why":"Use the narrowest appropriate sharing permission."}],"v":null},{"t":"Manage notifications and account settings","u":"نوٹیفکیشن اور اکاؤنٹ سیٹنگز","g":"Reduce noise while keeping important messages and account access.","points":[["Android settings can control app notifications individually, including sound and previews on the lock screen.","فون میں ہر ایپ کی نوٹیفکیشن الگ سے بند یا چالو کر سکتے ہیں۔"],["Turning off notifications is different from deleting an app or account.","نوٹیفکیشن بند کرنے سے ایپ یا اکاؤنٹ حذف نہیں ہوتا۔"],["Review Google Account → Personal info and Security for your recovery contact details.","گوگل اکاؤنٹ کی Security میں ریکوری تفصیلات درست رکھیں۔"],["Never share screenshots with one-time codes, account recovery details or private messages.","کوڈ یا نجی پیغام کا اسکرین شاٹ دوسروں کو نہ بھیجیں۔"]],"task":"Silence notifications for one nonessential app while leaving important calls and messages enabled.","taskUr":"غیرضروری ایپ کی اطلاع بند کریں، ضروری کالز چلتی رہنے دیں۔","qa":[{"question":"You want fewer shopping-app notifications, but still need bank alerts. Best method?","options":["Switch off every notification on the phone","Set notification preferences per app","Uninstall the phone's messaging app","Delete your Google account"],"answer":1,"why":"Per-app settings reduce distractions without hiding important notifications."},{"question":"You change your phone number. Why might updating Google recovery information matter?","options":["It changes the phone wallpaper","It can help you regain access to your account later","It increases RAM","It stops all spam automatically"],"answer":1,"why":"Outdated recovery details can make account recovery much harder."},{"question":"A notification shows a one-time login code. Should you send a screenshot of it to a caller who says they are support?","options":["Yes, but only once","No; the caller could use the code to enter your account","Yes, if they know your name","Yes, if the phone is locked"],"answer":1,"why":"The code is meant for your own verification, not the caller."}],"v":null},{"t":"Troubleshoot Android without losing data","u":"اینڈرائیڈ کی خرابی محفوظ طریقے سے ٹھیک کریں","g":"Work through problems without rushing into a factory reset.","points":[["Note whether the problem affects one app, every app, Wi-Fi, mobile data or the whole phone.","دیکھیں مسئلہ ایک ایپ کا ہے یا پورے فون کا۔"],["Check for app updates, free storage, permissions, and restart a stuck app or phone when appropriate.","ایپ اپ ڈیٹ، خالی جگہ، اجازتیں اور ری اسٹارٹ چیک کریں۔"],["Clearing app storage or resetting the phone can remove local data. Check backups and accounts first.","Clear data یا فیکٹری ری سیٹ سے معلومات ضائع ہو سکتی ہیں۔"],["Use the official brand support site or a trusted repair service if an error persists.","مسئلہ رہے تو اصل کمپنی کی مدد یا معتبر مرمت کی دکان جائیں۔"]],"task":"Write down one past phone problem and the first three safe checks you would try.","taskUr":"فون کے کسی مسئلے کے پہلے تین محفوظ حل لکھیں۔","qa":[{"question":"WhatsApp works on mobile data but not on home Wi-Fi. What is a useful next test?","options":["Reset every account password","Test another app and another device on that Wi-Fi","Delete your photos","Buy a new phone"],"answer":1,"why":"Comparing networks and devices narrows down the fault."},{"question":"One app closes immediately while all other apps work. Which action is proportionate first?","options":["Factory reset the entire phone","Update or restart that app and check its permissions/storage","Change the screen protector","Send personal details to random support accounts"],"answer":1,"why":"Start with the affected app before making drastic changes."},{"question":"Someone online recommends 'Clear storage' to fix an app without warning. Why pause?","options":["It will always delete your operating system","It may reset app data and remove locally stored information","It improves battery life too much","It is only available on iOS"],"answer":1,"why":"Clearing app storage can have consequences; verify important local data is backed up."}],"v":null},{"t":"Windows laptop essentials and settings","u":"ونڈوز لیپ ٹاپ کے ضروری کام","g":"Navigate Windows independently and know where key settings live.","points":[["Windows Settings manages updates, display, sound, Wi-Fi, accounts and connected devices.","ونڈوز کی Settings میں آواز، وائی فائی، اسکرین اور اپ ڈیٹس ہوتی ہیں۔"],["File Explorer is where you browse files and folders; Downloads and Documents are different locations.","File Explorer میں فائل اور فولڈر دیکھتے ہیں؛ Downloads اور Documents الگ جگہیں ہیں۔"],["Sleep, Restart, and Shut down do different things. Save work before restarting or shutting down.","Sleep، Restart اور Shut down میں فرق ہے؛ پہلے کام محفوظ کریں۔"],["Windows search can locate an app or setting without memorizing menus.","ونڈوز سرچ سے پروگرام اور سیٹنگ جلد مل جاتی ہے۔"]],"task":"On a Windows computer, find Settings, File Explorer and the Wi-Fi details; do not change anything important.","taskUr":"ونڈوز میں Settings، File Explorer اور Wi-Fi کی تفصیل تلاش کریں۔","qa":[{"question":"You want to update Windows but a document has unsaved changes. What first?","options":["Press Restart immediately","Save the document, then consider updates","Delete the Downloads folder","Remove the charger"],"answer":1,"why":"Updates and restarts can close programs; save your work first."},{"question":"You need to find the laptop's installed Windows version. Where is a reasonable place?","options":["Settings → System → About","Your email Sent folder","The laptop's wallpaper","The Recycle Bin"],"answer":0,"why":"System information is available in Settings."},{"question":"A laptop sleeps when its lid closes. Which statement is safest?","options":["Sleep is the same as securely backing up your work","Sleep saves power, but you should still save your document and have backups","Sleep deletes all documents","Sleep is a software update"],"answer":1,"why":"Sleep is not a substitute for saving or backing up."}],"v":null},{"t":"Keyboard shortcuts that save time","u":"کی بورڈ شارٹ کٹس جو کام آسان کریں","g":"Use shortcuts for copying text, searching, undoing and switching windows.","points":[["Ctrl+C copies, Ctrl+V pastes, Ctrl+X cuts, and Ctrl+Z undoes a recent action.","Ctrl+C نقل، Ctrl+V چسپاں، Ctrl+X منتقل، Ctrl+Z آخری عمل واپس۔"],["Ctrl+F searches within many documents and web pages; Ctrl+S saves in many programs.","Ctrl+F تلاش اور Ctrl+S محفوظ کرتا ہے۔"],["Alt+Tab changes between open windows; Windows+E opens File Explorer on Windows.","Alt+Tab سے ونڈو بدلیں، Windows+E سے فائل ایکسپلورر کھولیں۔"],["Shortcuts differ slightly between apps, and macOS often uses Command instead of Ctrl.","ہر ایپ میں شارٹ کٹ تھوڑا مختلف ہو سکتا ہے۔"]],"task":"Open a harmless document, copy one sentence, paste it, undo it and save the document.","taskUr":"کسی دستاویز میں جملہ کاپی، پیسٹ، اَن ڈو اور سیو کریں۔","qa":[{"question":"You accidentally deleted a paragraph in a text document but have not closed the editor. What should you try first?","options":["Ctrl+Z","Ctrl+X","Alt+F4","Windows+L"],"answer":0,"why":"Undo often reverses the most recent editing action."},{"question":"You need to find one word inside a long PDF. Which shortcut is usually quickest?","options":["Ctrl+P","Ctrl+F","Ctrl+N","Ctrl+Shift+Esc"],"answer":1,"why":"Find searches text in many PDF readers."},{"question":"You want to move rather than duplicate selected text inside a document. Which sequence is appropriate?","options":["Ctrl+C then Ctrl+C","Ctrl+X then Ctrl+V","Ctrl+S then Ctrl+F","Alt+Tab then Ctrl+P"],"answer":1,"why":"Cut removes from the original location and paste inserts it elsewhere."}],"v":null},{"t":"Organize files, folders and backups on Windows","u":"ونڈوز میں فائلیں، فولڈر اور بیک اپ","g":"Find, rename, move and back up documents without misplacing them.","points":[["Use Windows+E to open File Explorer and locate Downloads, Documents, Pictures and removable drives.","Windows+E سے فائلیں کھولیں؛ Downloads، Documents اور Pictures دیکھیں۔"],["Copy keeps the original; move changes the file's location. Rename changes the name, not file contents.","Copy سے اصل رہتی ہے، Move جگہ بدلتا ہے، Rename نام بدلتا ہے۔"],["Use meaningful names like Appointment-Nov2026.pdf; avoid deleting an unfamiliar file extension.","فائل کا واضح نام رکھیں، جیسے Appointment-Nov2026.pdf۔"],["A second copy on the same drive is not enough protection if the drive fails.","ایک ہی ڈرائیو میں دو کاپیاں مکمل بیک اپ نہیں۔"]],"task":"Make a folder 'Practice Documents', copy a non-sensitive PDF into it and rename the copy clearly.","taskUr":"Practice Documents فولڈر بنا کر عام پی ڈی ایف کی کاپی رکھیں اور نام بدلیں۔","qa":[{"question":"You need a second copy of a PDF but must keep the original in Downloads. Which action?","options":["Move it out of Downloads","Copy it into a new folder","Delete and recreate it","Rename the original only"],"answer":1,"why":"Copying preserves the original; moving relocates it."},{"question":"A USB drive holds the only copy of a scanned certificate. Is it properly backed up?","options":["Yes, USB drives never fail","Not yet; keep a verified independent copy","Yes, if the filename is long","Only if you rename the drive"],"answer":1,"why":"One remaining copy is not a resilient backup."},{"question":"After moving a file, where should you expect it?","options":["In both places forever","Only in the destination location, unless another copy exists","Automatically on every computer","Only in the Recycle Bin"],"answer":1,"why":"Moving changes the location rather than making a duplicate."}],"v":null},{"t":"Search smarter, use tabs and check websites","u":"ویب سرچ، ٹیب اور اصلی ویب سائٹ","g":"Find trustworthy information and avoid misleading results.","points":[["Search with precise terms, such as 'Newfoundland health card official application' instead of one vague word.","گوگل میں واضح الفاظ لکھیں، خاص طور پر سرکاری معلومات کے لیے۔"],["An advertisement or top-ranked result is not proof that a website is official. Check the domain.","سرچ میں پہلا نتیجہ یا اشتہار ہمیشہ اصل ویب سائٹ نہیں ہوتا۔"],["Use tabs, bookmarks and browser history to return to information, but private browsing does not make you anonymous.","ٹیب اور بک مارک سے صفحات دوبارہ کھولیں؛ پرائیویٹ موڈ مکمل گمنامی نہیں۔"],["Look for an official source, recent date and direct evidence for important instructions.","اہم بات کے لیے سرکاری ذریعہ، تاریخ اور ثبوت دیکھیں۔"]],"task":"Search for an official public-service page, bookmark it and compare it with one search advertisement.","taskUr":"کسی سرکاری صفحے کو سرچ کریں، بک مارک کریں اور اشتہار سے فرق دیکھیں۔","qa":[{"question":"A search ad says 'Official password recovery' but its domain is unrelated to Google. What should you do?","options":["Trust the word Official","Go to Google's known sign-in/recovery page directly","Submit your old password to confirm","Call the number in the advertisement"],"answer":1,"why":"Search titles and ads can mislead; verify the domain."},{"question":"You closed a useful webpage by accident. Which tools might help locate it again?","options":["Browser history or bookmarks","The SIM contacts list","The phone torch","The wallpaper gallery"],"answer":0,"why":"History and bookmarks help return to pages."},{"question":"Why is a private-browsing tab not equal to being anonymous online?","options":["It can stop the internet","Websites and networks can still observe activity and your public IP","It destroys your account","It deletes every local file"],"answer":1,"why":"Private browsing mainly limits some local browsing history; it is not total anonymity."}],"v":null},{"t":"Download, edit and share PDFs","u":"پی ڈی ایف ڈاؤن لوڈ، ترمیم اور بھیجنا","g":"Handle PDFs for appointments and applications without losing the originals.","points":[["A PDF is a document format; it may contain scanned pictures, selectable text or fillable fields.","پی ڈی ایف میں اسکین تصویر، لکھائی یا بھرنے والے خانے ہو سکتے ہیں۔"],["Download creates a device copy; upload sends a copy to a website or email service.","ڈاؤن لوڈ آپ کے پاس، اپ لوڈ دوسرے نظام میں فائل بھیجتا ہے۔"],["Use the real PDF viewer to fill fields where supported, and save a new copy with a clear name.","پی ڈی ایف میں اگر فارم بھر سکتے ہوں تو نئی کاپی محفوظ کریں۔"],["Check file extension, total pages, completeness and recipient before sharing.","بھیجنے سے پہلے فائل کی قسم، صفحات اور نام دیکھیں۔"]],"task":"Download a public form PDF, check its page count and make a practice copy with a clear name.","taskUr":"عام فارم پی ڈی ایف ڈاؤن لوڈ کر کے صفحات چیک کریں اور نئی کاپی بنائیں۔","qa":[{"question":"A website asks for one PDF, but you only have three scanned JPG images. What is appropriate?","options":["Rename .jpg files to .pdf","Create or combine them into an actual PDF and verify the pages","Send a screenshot of the gallery","Upload a random .exe file"],"answer":1,"why":"Changing an extension does not convert a file; create a real PDF."},{"question":"An attachment named letter.pdf.exe arrives unexpectedly. What is the correct concern?","options":["It may be an executable program disguised as a PDF","It must be a safe PDF","It is an ordinary image","It only works on a printer"],"answer":0,"why":"The actual file extension may indicate executable software."},{"question":"After editing a PDF form, what prevents accidentally overwriting the blank original?","options":["Save as a new file with a distinct name","Close the device without saving","Rename the USB drive","Turn off the router"],"answer":0,"why":"A separate named copy preserves the blank original."}],"v":null},{"t":"Write and send useful emails","u":"مفید ای میل لکھیں اور بھیجیں","g":"Compose clear emails for work, schools and appointments.","points":[["To contains the recipient address; Subject is the purpose; Body contains the message.","To میں پتہ، Subject میں مقصد، Body میں پیغام لکھیں۔"],["Choose a clear subject such as 'Appointment document – November 10' rather than 'Hi'.","عنوان واضح رکھیں، مثلاً Appointment document۔"],["Attachments need to finish uploading before you send; inspect file name and recipient.","Send دبانے سے پہلے فائل اپ لوڈ ہونے اور پتہ درست ہونے کی تصدیق کریں۔"],["Sent shows messages you have sent. A missing email in Sent may mean it is still in Drafts or Outbox.","Sent میں بھیجی ای میل، Drafts میں ادھورا پیغام ہوتا ہے۔"]],"task":"Compose a practice email to yourself with a clear subject, two sentences and a non-sensitive attachment. Verify it appears in Sent.","taskUr":"خود کو ایک ٹیسٹ ای میل صاف عنوان، دو جملوں اور عام فائل کے ساتھ بھیجیں۔","qa":[{"question":"You attached a document but it still shows 'Uploading'. What should you do?","options":["Send immediately and assume it attached","Wait for upload to finish and verify the file","Delete the subject","Change the email password"],"answer":1,"why":"Incomplete uploads can result in missing attachments."},{"question":"You typed an email yesterday but it never arrived. Where should you check to see whether it was sent?","options":["Only Spam","Sent, Drafts and Outbox as applicable","The phone camera","Wi-Fi passwords"],"answer":1,"why":"Drafts and Outbox can hold messages that have not been sent."},{"question":"You notice the email address autocompleted to a similarly named contact. Safest action?","options":["Verify the full address before sending","Trust the display name alone","Add both contacts just in case","Remove the attachment but send anyway"],"answer":0,"why":"A wrong recipient could receive personal information."}],"v":{"id":"Cn43fziqi6w","label":"Gmail: send emails and attachments on phone or computer","start":0}},{"t":"Manage your inbox and email attachments","u":"ان باکس، جواب اور اٹیچمنٹ","g":"Handle replies, forwarded messages and files responsibly.","points":[["Reply normally responds to the sender; Reply all may include a whole group.","Reply سے ایک شخص اور Reply all سے کئی افراد جواب پا سکتے ہیں۔"],["Forwarding can pass along earlier email text and attachments, including private details.","Forward سے پہلے کے نجی پیغامات بھی دوسرے تک پہنچ سکتے ہیں۔"],["Search Gmail using sender, subject or words; labels and archive help organize without deleting.","جی میل میں سرچ اور لیبل سے پیغام ڈھونڈیں؛ Archive ڈیلیٹ نہیں۔"],["Never open suspicious attachments or enter a password from a random email link.","مشکوک ای میل کی فائل یا لنک نہ کھولیں۔"]],"task":"Find an old non-sensitive email using search, reply to a trusted test message, and archive a practice message.","taskUr":"سرچ سے ایک پرانا پیغام ڈھونڈیں، جواب دیں اور ٹیسٹ ای میل آرکائیو کریں۔","qa":[{"question":"A message includes a large group. You want to respond only to the organizer. Which action?","options":["Reply all","Reply","Forward to all","Cc everyone"],"answer":1,"why":"Reply all can disclose your response to the full group."},{"question":"You archived an important email. How can you usually find it again?","options":["Search or All Mail","It is permanently deleted","Only by resetting your password","It can be found only on a printer"],"answer":0,"why":"Archive removes it from Inbox, not necessarily from the account."},{"question":"A forwarded email contains another person's personal address. Before sending it to a new person?","options":["Forward unchanged to save time","Remove private details you should not share or obtain permission","Add more recipients","Turn off spam protection"],"answer":1,"why":"Forwarded history can expose information not meant for the new recipient."}],"v":null},{"t":"Recover a forgotten Google or email password","u":"گوگل یا ای میل پاس ورڈ بھول جائیں تو","g":"Use official recovery, trusted devices and recovery options safely.","points":[["For Gmail, begin at accounts.google.com/signin/recovery or your Google account's official sign-in page.","جی میل کے لیے گوگل کی اصل ریکوری ویب سائٹ استعمال کریں۔"],["Follow Google identity checks using available recovery phone, recovery email or trusted devices.","گوگل آپ کے ریکوری فون یا ای میل سے تصدیق کر سکتا ہے۔"],["If asked to wait or try again later, follow official instructions; nobody can guarantee instant recovery.","کبھی تصدیق میں وقت لگتا ہے؛ کوئی فوری گارنٹی نہیں دے سکتا۔"],["Never share one-time verification codes with callers or people offering to 'recover' an account.","تصدیقی کوڈ کسی کو نہ دیں چاہے وہ مدد کا دعویٰ کرے۔"]],"task":"Find the official Google account recovery page without starting a reset, and check whether your recovery contact information is current.","taskUr":"گوگل کی اصل ریکوری ویب سائٹ دیکھیں اور اپنی ریکوری تفصیلات کی تصدیق کریں۔","qa":[{"question":"You receive an unexpected password reset link by SMS. What is safest?","options":["Open the official Google site yourself and check account security","Tap the message's link because it is convenient","Reply with your current password","Forward the link to a stranger for verification"],"answer":0,"why":"Navigate independently to the official service rather than trusting unsolicited links."},{"question":"Google says it needs an identity check. A caller offers a faster solution if you tell them a code. What should you do?","options":["Tell them the code once","Share the code but not the password","Do not share the code; use only official recovery steps","Post it in a family group"],"answer":2,"why":"Recovery codes and one-time codes are secrets."},{"question":"You cannot sign in on a new phone but are still signed in on an old trusted device. Best next move?","options":["Factory reset the old device immediately","Use the official account security/recovery options on the trusted device","Give the old device to a caller","Delete every recovery email"],"answer":1,"why":"A trusted signed-in device may offer legitimate ways to verify your identity."}],"v":null},{"t":"Strong passwords and 2-step verification","u":"مضبوط پاس ورڈ اور دو مرحلے","g":"Protect accounts and recovery details.","points":[["Use a unique, long password or passphrase for each important account.","ہر اہم اکاؤنٹ کا الگ اور طویل پاس ورڈ رکھیں۔"],["A trusted password manager can help store and fill passwords securely.","قابلِ اعتماد پاس ورڈ مینیجر استعمال کیا جا سکتا ہے۔"],["2-step verification adds a second check. Save official recovery methods in a secure place.","دو مرحلوں کی تصدیق میں اضافی حفاظت ہوتی ہے۔"]],"task":"Find your account's Security settings and check that recovery information is current.","taskUr":"اکاؤنٹ کی Security سیٹنگز میں ریکوری تفصیلات دیکھیں۔","qa":[{"question":"A password is long but reused on 5 websites. What is its biggest weakness?","options":["It has too many characters","One breach may expose all five accounts","It cannot work on a phone","It requires Wi-Fi"],"answer":1,"why":"Reusing even a strong password spreads the risk of one breach."},{"question":"An unexpected sign-in approval appears on your device. Which response is best?","options":["Approve to stop notifications","Ignore then review account security directly; deny the request","Give the person a one-time code","Turn off all security features"],"answer":1,"why":"Unexpected prompts can be an attack; never approve a sign-in you did not start."}],"v":null},{"t":"Cloud storage and backups","u":"کلاؤڈ اور بیک اپ","g":"Know what is on the phone and what is online.","points":[["Cloud storage keeps files on online servers associated with an account.","کلاؤڈ انٹرنیٹ پر فائلیں محفوظ کر سکتا ہے۔"],["Sync means changes travel between devices; it is not always an independent backup.","سنک سے تبدیلی دوسرے آلے میں بھی آ سکتی ہے، یہ ہمیشہ بیک اپ نہیں۔"],["Keep an additional copy of truly important files and test that it opens.","ضروری دستاویز کی اضافی نقل رکھیں اور کھول کر دیکھیں۔"]],"task":"Find whether your phone backs up photos. Do not delete any photos for practice.","taskUr":"دیکھیں تصاویر کا بیک اپ کہاں ہے؛ کچھ حذف نہ کریں۔","qa":[{"question":"Your photos sync to the cloud. You delete a photo on your phone. What could happen?","options":["The cloud must keep it forever","The deletion may sync to the cloud","The phone makes a printed copy","The phone converts it to email"],"answer":1,"why":"Syncing a deletion does not guarantee a separate backup survives."},{"question":"Which arrangement best protects an important scanned certificate?","options":["Keep it only in one downloads folder","Keep it only in a synced photo gallery","Keep a verified additional copy somewhere separate and secure","Only change its filename"],"answer":2,"why":"A separate verified backup protects against deletion, loss and sync mistakes."}],"v":null},{"t":"Online forms, video meetings and appointments","u":"آن لائن فارم اور ملاقات","g":"Submit documents accurately and attend calls confidently.","points":[["Review a website's identity before submitting sensitive online forms, especially government or banking forms.","ذاتی معلومات والا فارم بھرنے سے پہلے اصل ویب سائٹ دیکھیں۔"],["Confirm names, dates, phone numbers, attachments and any required fields before Submit.","Submit سے پہلے نام، تاریخ اور فائلیں دوبارہ چیک کریں۔"],["On video calls, learn mute, camera, speaker selection and permissions in the app you actually use.","ویڈیو کال میں مائیک، کیمرہ اور اسپیکر کی سیٹنگ سمجھیں۔"],["Keep confirmation numbers or emails; never assume a form was submitted without confirmation.","فارم کے بعد تصدیقی نمبر یا ای میل محفوظ رکھیں۔"]],"task":"Fill a harmless sample form or an unsent draft, and inspect all fields as though it were an application.","taskUr":"ٹیسٹ فارم کے تمام خانے چیک کریں اور تصدیق کی جگہ دیکھیں۔","qa":[{"question":"After attaching a PDF to a form, what check best prevents an incomplete application?","options":["Assume every upload is fine","Confirm correct file name, pages and successful upload status","Rename the browser tab","Close the page immediately"],"answer":1,"why":"A document can be wrong or incompletely uploaded despite being selected."},{"question":"You click Submit but the page gives no receipt or confirmation. Best next action?","options":["Submit repeatedly without checking","Check for confirmation or status before deciding whether to resubmit","Assume it was approved","Share your password to get help"],"answer":1,"why":"Checking status helps prevent duplicate submissions."},{"question":"Your camera works in one app but not a video meeting app. What may be relevant?","options":["That app's camera permission","The screen saver image","The RAM brand","Your email signature"],"answer":0,"why":"Permissions can be granted per app."}],"v":null},{"t":"Phishing, scams and fake support","u":"فراڈ اور جعلی پیغامات","g":"Spot urgent messages that try to trick you.","points":[["Scams may pretend to be banks, delivery companies, employers or government offices.","فراڈ پیغام بینک یا سرکاری ادارے کے نام سے آ سکتا ہے۔"],["Urgency, odd addresses and requests for codes or remote access are warning signs.","جلد بازی، عجیب لنک اور کوڈ مانگنا خطرے کی نشانیاں ہیں۔"],["If uncertain, contact the organization using its known official app/number, not the message link.","شک ہو تو اصل ایپ یا سرکاری نمبر سے رابطہ کریں۔"]],"task":"With a family member, examine a harmless sample scam message and name two warning signs.","taskUr":"گھر والوں کے ساتھ فرضی فراڈ پیغام کی دو نشانیاں پہچانیں۔","qa":[{"question":"A text says your parcel will be destroyed in 30 minutes unless you pay a fee via a link. What first?","options":["Pay immediately because it is urgent","Use the delivery company's official site/app to check the tracking number","Reply with your credit-card number","Forward the link to everyone"],"answer":1,"why":"Urgent threats and payment links are common scam patterns."},{"question":"A caller says they are technical support and need remote control of your screen.","options":["Allow if they know your email","Give them a one-time code first","Decline and independently contact trusted support if needed","Install the tool to see if it works"],"answer":2,"why":"Unrequested remote-access requests are high risk."}],"v":null},{"t":"Online shopping and banking safely","u":"آن لائن خریداری اور بینک","g":"Handle payments cautiously.","points":[["Open your bank or shop from a known official app or typed website address.","بینک یا خریداری کی اصل ایپ کھولیں۔"],["Check total price, delivery, returns and payment recipient before confirming.","ادائیگی سے پہلے قیمت، ڈیلیوری اور واپسی کی شرط دیکھیں۔"],["Never share your PIN, bank password or verification code with a caller or seller.","پن، بینک پاس ورڈ اور تصدیقی کوڈ کسی کو نہ دیں۔"]],"task":"Practise reviewing a shopping basket without placing an order or entering payment details.","taskUr":"بغیر خریدے شاپنگ کارٹ کی تفصیلات دیکھیں۔","qa":[{"question":"A seller wants an e-transfer to a personal account outside the marketplace to get a 'discount'. What risk?","options":["It guarantees a refund","You may lose buyer protection and send money to a scammer","It makes the item tax-free","It speeds up your Wi-Fi"],"answer":1,"why":"Off-platform payments can be harder to dispute or recover."},{"question":"You receive a bank security text with a link. What is the safest check?","options":["Use the text's link only","Tell the text your PIN","Open your bank app directly or call the official number on your card","Share a screenshot with strangers"],"answer":2,"why":"Start from a known trusted banking channel, not an unexpected link."}],"v":null},{"t":"Privacy and reliable information","u":"پرائیویسی اور درست معلومات","g":"Decide what to trust or share.","points":[["Do not post personal identity numbers, addresses or private documents in public places.","شناختی نمبر اور ذاتی دستاویز عام جگہ پر نہ رکھیں۔"],["Check dates, authors and official sources before sharing important claims.","اہم خبر کی تاریخ اور اصل ذریعہ دیکھیں۔"],["Location sharing is useful sometimes, but review who can see it and for how long.","لوکیشن کس کے ساتھ اور کب تک شیئر ہو رہی ہے دیکھیں۔"]],"task":"Find the location-sharing setting on your phone; do not change it without deciding.","taskUr":"فون میں لوکیشن شیئرنگ کی جگہ تلاش کریں۔","qa":[{"question":"A health message has thousands of likes but no reliable source. Best interpretation?","options":["Likes prove medical accuracy","It is safe because someone forwarded it","Popularity alone is not evidence; check trusted medical sources","The colour of the message proves it"],"answer":2,"why":"Popularity and accuracy are not the same."},{"question":"A photo contains a visible document with your home address. What should you do before posting?","options":["Post it because it is only a photo","Remove or hide the private details","Add more hashtags","Turn on airplane mode"],"answer":1,"why":"Pictures can reveal private information even without typed text."}],"v":null},{"t":"Solve common phone and laptop problems","u":"فون اور لیپ ٹاپ کی عام خرابی","g":"Systematically identify software, connection and storage problems.","points":[["Ask whether the fault affects one app, one device, one network or all devices.","معلوم کریں مسئلہ ایک ایپ، ایک آلہ یا پورے نیٹ ورک میں ہے۔"],["Check updates, permissions, storage and connection before drastic repair steps.","اپ ڈیٹس، اجازتیں، اسٹوریج اور نیٹ ورک پہلے دیکھیں۔"],["Write down the exact error message and what happened just before it.","خرابی کا اصل پیغام اور پہلے کیا ہوا تھا وہ نوٹ کریں۔"],["Check backups and seek trusted advice before factory reset, deleting files or giving remote access.","بیک اپ کے بغیر ری سیٹ نہ کریں اور اجنبی کو ریموٹ رسائی نہ دیں۔"]],"task":"Pick one real device problem and create a three-step troubleshooting checklist.","taskUr":"اپنے کسی مسئلے کے لیے تین مرحلوں کی چیک لسٹ بنائیں۔","qa":[{"question":"All apps work except one that crashes on opening. First sensible checks?","options":["App update, available storage and its permissions","Replace the entire computer","Reset every account","Delete all personal documents"],"answer":0,"why":"App-specific checks should come before device-wide changes."},{"question":"Your laptop connects to Wi-Fi but a phone on the same Wi-Fi also has no internet. What should you suspect?","options":["The laptop's GPU","Router or internet service, not just one device","Both screens","The keyboard layout"],"answer":1,"why":"The issue affects multiple devices on the same network."},{"question":"An online 'technician' insists on remote access and your bank password before explaining a problem. Best response?","options":["Comply if they sound polite","Refuse and find the real support channel independently","Share only the bank password","Disable security warnings"],"answer":1,"why":"Legitimate support does not require your banking credentials."}],"v":null},{"t":"Hardware, software and operating systems","u":"ہارڈویئر اور سافٹ ویئر","g":"Know what is physical and what is a program.","points":[["Hardware is what you can touch: screen, keyboard, CPU, RAM, SSD and cables.","ہارڈویئر وہ حصے ہیں جنہیں چھو سکتے ہیں۔"],["Software is instructions: operating systems, browsers and apps.","سافٹ ویئر وہ پروگرام ہیں جو کمپیوٹر چلاتے ہیں۔"],["The operating system manages hardware and helps apps run.","آپریٹنگ سسٹم ہارڈویئر اور ایپس کو چلانے میں مدد دیتا ہے۔"]],"task":"Point out five pieces of hardware on a laptop or phone.","taskUr":"لیپ ٹاپ یا فون میں ہارڈویئر کے پانچ حصے بتائیں۔","qa":[{"question":"Which of these is software rather than hardware?","options":["RAM chip","Windows operating system","SSD drive","Keyboard"],"answer":1,"why":"Windows is a program; the others are physical components."},{"question":"A computer has a working screen and keyboard but no usable operating system installed. What is most accurate?","options":["All normal apps will work anyway","The machine may power on but ordinary apps cannot run normally","It must be a tablet","The CPU becomes storage"],"answer":1,"why":"The operating system is needed for normal interaction and app management."}],"v":{"id":"dMx5HjeBFv4","label":"Computer parts explained: motherboard, CPU, RAM and more","start":0}},{"t":"CPU and motherboard","u":"سی پی یو اور مدربورڈ","g":"Meet the processor and main circuit board.","points":[["CPU (processor) carries out calculations and instructions, like the computer's worker.","سی پی یو حساب اور ہدایات پر عمل کرتا ہے۔"],["Motherboard connects the CPU, RAM, storage and other components.","مدربورڈ دوسرے اہم حصوں کو جوڑتا ہے۔"],["Cooling helps a CPU avoid overheating when working hard.","کولنگ سسٹم سی پی یو کو زیادہ گرم ہونے سے بچاتا ہے۔"]],"task":"Use a drawing to connect CPU, RAM and storage to the motherboard.","taskUr":"کاغذ پر سی پی یو، ریم اور اسٹوریج کو مدربورڈ سے جوڑ کر بنائیں۔","qa":[{"question":"Your laptop's processor is busy while opening many programs. What part is doing the instructions?","options":["Monitor","CPU","SSD case","Charger cable"],"answer":1,"why":"The CPU executes instructions; storage holds files."},{"question":"The CPU works, but the motherboard is badly damaged. What is likely?","options":["The components may no longer communicate properly","A faster Wi-Fi password fixes it","Extra brightness repairs it","The CPU becomes ROM"],"answer":0,"why":"The motherboard provides major connections between components."}],"v":{"id":"dMx5HjeBFv4","label":"Computer components: CPU, RAM, storage and motherboard","start":70}},{"t":"RAM: short-term working memory","u":"ریم: عارضی کام کرنے والی میموری","g":"Learn why RAM is not the same as storage.","points":[["RAM holds information programs are actively using; it is fast but temporary.","ریم چلتے پروگراموں کی معلومات وقتی طور پر رکھتی ہے۔"],["RAM contents normally disappear when power is lost.","بجلی بند ہونے پر ریم کا عارضی ڈیٹا ختم ہو جاتا ہے۔"],["More RAM can help multitasking, but does not replace SSD storage.","زیادہ ریم سے کئی ایپس چل سکتی ہیں، یہ اسٹوریج نہیں۔"]],"task":"Explain to a relative how RAM differs from the folder where photos are saved.","taskUr":"کسی کو سمجھائیں ریم اور تصاویر کی محفوظ جگہ میں کیا فرق ہے۔","qa":[{"question":"Your laptop slows when many browser tabs and apps are open. What upgrade MAY help if memory is the bottleneck?","options":["More RAM","Bigger screen","Faster charger","New wallpaper"],"answer":0,"why":"More RAM may improve multitasking when available memory is insufficient."},{"question":"You save a photo, then shut down the laptop. Why can it still be there next day?","options":["RAM stored it forever","The CPU memorized it","It was saved to persistent storage, such as SSD or HDD","The screen retained it"],"answer":2,"why":"Photos persist on storage; RAM is temporary."}],"v":{"id":"dMx5HjeBFv4","label":"Computer components: CPU, RAM, storage and motherboard","start":207}},{"t":"ROM, firmware and startup","u":"روم اور سسٹم شروع ہونا","g":"Understand the difference between RAM and ROM.","points":[["ROM means read-only memory; it historically stores essential instructions that do not vanish when power is off.","روم ایسی میموری ہے جو اہم ہدایات محفوظ رکھتی ہے۔"],["Modern devices often use reprogrammable flash memory for firmware (including UEFI/BIOS).","آج کے آلات میں فرم ویئر اکثر فلیش میموری میں ہوتا ہے۔"],["Phone '128 GB ROM' often means internal storage in advertisements, not strict technical ROM.","فون کے اشتہار میں ROM لکھا ہو تو اکثر اندرونی اسٹوریج مراد ہوتی ہے۔"]],"task":"Compare the labels '8 GB RAM' and '128 GB storage' on a sample phone listing.","taskUr":"فون کی مثال میں 8 GB RAM اور 128 GB storage کا فرق بتائیں۔","qa":[{"question":"A phone ad says '8 GB RAM, 128 GB ROM'. What does '128 GB ROM' usually mean in this advertising context?","options":["The CPU frequency","Internal persistent storage","How many apps can run simultaneously","A replaceable battery"],"answer":1,"why":"Phone marketing sometimes calls internal flash storage 'ROM'; technically it is not strict read-only ROM."},{"question":"What distinguishes RAM from boot firmware storage?","options":["RAM always stays after power-off","Firmware storage is nonvolatile, while typical RAM is volatile","Both are just screens","Firmware is the same as Wi-Fi"],"answer":1,"why":"Firmware remains available across restarts; typical RAM loses its contents."}],"v":null},{"t":"SSD, HDD and USB storage","u":"ایس ایس ڈی، ہارڈ ڈرائیو اور یو ایس بی","g":"Learn where files live permanently.","points":[["An SSD stores files using flash memory and usually feels faster than a hard disk.","ایس ایس ڈی فلیش میموری سے فائلیں رکھتی ہے اور عموماً تیز ہوتی ہے۔"],["An HDD uses spinning magnetic disks and may be larger for lower cost.","ایچ ڈی ڈی گھومنے والی ڈسک پر فائل محفوظ کرتی ہے۔"],["USB drives and external disks can carry copies, but they can fail or be lost.","یو ایس بی میں فائل کی نقل رکھی جا سکتی ہے مگر وہ گم بھی ہو سکتی ہے۔"]],"task":"Find how much storage your phone or computer has. Do not delete anything.","taskUr":"دیکھیں آلے میں کتنی اسٹوریج ہے؛ کچھ ڈیلیٹ نہ کریں۔","qa":[{"question":"A laptop has plenty of RAM but almost no free SSD space. What can happen?","options":["It will have unlimited file space anyway","It may struggle to save new files or updates","RAM automatically turns into SSD","The display resolution increases"],"answer":1,"why":"RAM and persistent storage have different roles; low free storage still matters."},{"question":"You copy a document onto one USB drive and delete it from the laptop. Is that a robust backup?","options":["Yes, any USB can never fail","Yes, because RAM remains","Not really; there is only one remaining copy","Only if the USB is blue"],"answer":2,"why":"A single remaining copy can still be lost; keep independent backups."}],"v":{"id":"dMx5HjeBFv4","label":"Computer components: CPU, RAM, storage and motherboard","start":189}},{"t":"GPU, display and input/output","u":"جی پی یو اور ان پٹ آؤٹ پٹ","g":"Understand images and information flow.","points":[["GPU helps render images and video; some computers use graphics built into the processor.","جی پی یو تصویروں اور ویڈیو کو دکھانے میں مدد دیتا ہے۔"],["Keyboard, touchpad, camera and microphone are input devices.","کی بورڈ، کیمرہ اور مائیک معلومات اندر دیتے ہیں۔"],["Screen, speakers and printer are output devices.","اسکرین، اسپیکر اور پرنٹر نتیجہ دکھاتے یا سناتے ہیں۔"]],"task":"Find two input devices and two output devices around you.","taskUr":"اپنے آس پاس دو ان پٹ اور دو آؤٹ پٹ آلات تلاش کریں۔","qa":[{"question":"During a video call, what is the role of your microphone?","options":["Output because sound exits it","Input because it captures your voice","Persistent storage","Wireless router"],"answer":1,"why":"The microphone brings sound into the computer as input."},{"question":"A computer displays video through integrated graphics. What does that imply?","options":["It has no graphics capability","Graphics processing can be built into the CPU/chip","The SSD is showing the pixels","The monitor is the CPU"],"answer":1,"why":"Many chips include an integrated GPU rather than a separate graphics card."}],"v":{"id":"dMx5HjeBFv4","label":"Computer components: CPU, RAM, storage and motherboard","start":0}},{"t":"Ports, power, cooling and networks","u":"پورٹس، بجلی اور نیٹ ورک","g":"Understand what the plugs and fans do.","points":[["USB connects accessories, HDMI carries audio/video to a screen, and charging ports supply power.","یو ایس بی چیزیں جوڑتا ہے، ایچ ڈی ایم آئی ویڈیو لے جاتا ہے۔"],["Fans and heatsinks help remove heat; blocked vents may cause overheating.","پنکھے اور کولنگ حصے گرمی باہر نکالتے ہیں۔"],["A router directs network traffic at home; Bluetooth connects nearby accessories.","روٹر نیٹ ورک جوڑتا ہے، بلوٹوتھ قریبی آلات جوڑتا ہے۔"]],"task":"Identify a USB port, charging port and ventilation area on a laptop.","taskUr":"لیپ ٹاپ پر USB، چارجر اور ہوا کی جگہ پہچانیں۔","qa":[{"question":"You want to show a laptop presentation on a TV that accepts HDMI. Which connection is suitable?","options":["HDMI cable/adaptor","A phone SIM","CPU fan connector","Microphone mute"],"answer":0,"why":"HDMI can carry display video to a compatible screen."},{"question":"Your laptop gets hot when its vents are blocked by a blanket. First sensible action?","options":["Keep vents covered for comfort","Use it on a firm surface with clear vents","Delete all browser history","Turn up screen brightness"],"answer":1,"why":"Airflow is important for cooling and safety."}],"v":{"id":"dMx5HjeBFv4","label":"Computer ports, connectors and cooling","start":258}},{"t":"Final practice: solve it yourself","u":"آخری مشق: خود حل کریں","g":"Bring everyday digital skills together.","points":[["Look closely at the problem before pressing anything.","بٹن دبانے سے پہلے مسئلہ غور سے دیکھیں۔"],["Try simple checks first: battery, connection, permissions, correct app or file.","پہلے بیٹری، کنکشن اور صحیح ایپ دیکھیں۔"],["Protect accounts: use official sites, independent verification, and never share codes.","اصل ویب سائٹ استعمال کریں اور کوڈ کسی کو نہ دیں۔"]],"task":"Explain when you would use Android's file manager, Gmail, Google account recovery, and the difference between RAM and SSD to a family member.","taskUr":"کسی گھر والے کو فائل مینیجر، جی میل، اکاؤنٹ ریکوری اور RAM بمقابلہ SSD سمجھائیں۔","qa":[{"question":"You cannot attach an appointment PDF because the email app cannot find it. Best sequence?","options":["Factory-reset the phone","Check Downloads/Files, then return to the attachment picker","Send your password to support","Remove Wi-Fi permanently"],"answer":1,"why":"First locate the file, then attach it in the mail app."},{"question":"A stranger phones saying they need a sign-in code to fix your slow laptop. Which combination is best?","options":["Give the code and restart","Share screen and bank details","Decline, independently seek help if necessary, and never share the code","Install any program they request"],"answer":2,"why":"Support calls cannot justify sharing codes or allowing unrequested remote access."}],"v":{"id":"dMx5HjeBFv4","label":"Computer components: CPU, RAM, storage and motherboard","start":0}}];
